// Original code-drawn early-era art. Modern military sprites remain in the atlases.
export const EARLY=new Set(['camp','house','farm','mine','barracks','market','tower','dock','depot','embassy']);
function poly(c,points,color,stroke=null){c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();c.fillStyle=color;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=.7;c.stroke();}}
function hut(c,x,y,s=1,roof='#bda36a'){c.save();c.translate(x,y);c.scale(s,s);poly(c,[[-35,-12],[7,3],[37,-13],[-4,-28]],'#645f46');poly(c,[[-31,-18],[4,-4],[4,-42],[-31,-56]],'#a88d5e');poly(c,[[4,-4],[33,-19],[33,-57],[4,-42]],'#7d704b');for(let i=0;i<5;i++){c.strokeStyle='#665a3b66';c.beginPath();c.moveTo(-30,-23-i*6);c.lineTo(3,-10-i*6);c.stroke();}poly(c,[[-40,-53],[-4,-79],[10,-39]],roof);poly(c,[[-4,-79],[42,-58],[10,-39]],'#8c774d');poly(c,[[-16,-12],[-4,-7],[-4,-32],[-16,-37]],'#394238');poly(c,[[17,-31],[26,-35],[26,-47],[17,-43]],'#b8c6a0');c.restore();}
export function earlyBuilding(c,type,x,y,scale=1){c.save();c.translate(x,y);c.scale(scale,scale);c.fillStyle='#132d3038';c.beginPath();c.ellipse(0,4,62,22,0,0,7);c.fill();poly(c,[[-62,0],[-5,24],[65,-3],[7,-29]],'#8b9570');if(type==='tower'){poly(c,[[-19,0],[6,11],[6,-71],[-19,-82]],'#a7aa8b');poly(c,[[6,11],[25,0],[25,-82],[6,-71]],'#6e7b68');poly(c,[[-27,-81],[-1,-94],[33,-81],[7,-67]],'#c7c4a4');for(let i=0;i<3;i++)poly(c,[[-25+i*12,-79],[-19+i*12,-76],[-19+i*12,-88],[-25+i*12,-91]],'#bdc1a3');poly(c,[[-8,-25],[1,-21],[1,-43],[-8,-47]],'#3e4d45');}
else if(type==='dock'){poly(c,[[-65,-4],[-5,22],[66,-5],[5,-30]],'#a38c5e');for(let i=0;i<8;i++){c.strokeStyle='#dac396';c.beginPath();c.moveTo(-59+i*8,-3+i*3.4);c.lineTo(10+i*7,-27+i*3.2);c.stroke();}hut(c,-15,-12,.55);for(const [xx,yy]of[[-58,-3],[-5,18],[60,-5]]){c.fillStyle='#806e4b';c.fillRect(xx,yy-12,4,20);}}
else if(type==='farm'){hut(c,-22,-7,.65);for(let row=0;row<4;row++)for(let col=0;col<5;col++){const xx=4+col*7-row*6,yy=-12+col*3+row*4;c.strokeStyle='#d1c481';c.lineWidth=2;c.beginPath();c.moveTo(xx,yy);c.lineTo(xx-1,yy-11);c.stroke();c.fillStyle='#c7cb7c';c.fillRect(xx-3,yy-12,4,4);}}
else if(type==='mine'){poly(c,[[-49,0],[-27,-54],[12,-68],[48,-17],[20,13]],'#858f83');poly(c,[[-27,-54],[12,-68],[6,-15],[-49,0]],'#a5ac99');poly(c,[[-15,2],[16,11],[26,-26],[-4,-39]],'#253e3d');poly(c,[[-19,1],[-14,4],[-4,-36],[-9,-39]],'#b79c70');poly(c,[[-7,-40],[28,-27],[28,-22],[-9,-35]],'#c5af80');for(let i=0;i<4;i++)poly(c,[[0+i*5,12+i*2],[6+i*5,14+i*2],[24+i*5,6+i*2],[18+i*5,4+i*2]],'#b0a17e');}
else{hut(c,-13,-4,type==='camp'?.95:.8,type==='barracks'?'#9d735c':type==='embassy'?'#829b91':'#c0ac78');if(['camp','house','market','depot'].includes(type))hut(c,32,3,.48,'#aa9b6d');if(type==='market'){poly(c,[[9,-12],[37,-1],[48,-26],[20,-37]],'#8aa28b');for(let i=0;i<3;i++){c.fillStyle='#c3b77b';c.fillRect(14+i*9,-8+i*2,6,8);}}if(type==='camp'||type==='embassy'){c.strokeStyle='#786b49';c.lineWidth=2;c.beginPath();c.moveTo(-49,1);c.lineTo(-49,-59);c.stroke();poly(c,[[-48,-59],[-27,-51],[-48,-40]],'#b9c89a');}}
c.restore();}
export function earlyUnit(c,type,x,y,scale=1,walking=false,time=0){c.save();c.translate(x,y);c.scale(scale,scale);if(type==='plane'){poly(c,[[-46,-27],[4,-39],[28,-31],[9,-20]],'#9caeaa');poly(c,[[-10,-56],[-4,-58],[10,-21],[5,-2],[-2,-4]],'#d0d7c2');poly(c,[[-16,-10],[16,-16],[18,-10],[-8,-4]],'#8b9f9c');poly(c,[[-4,-51],[3,-49],[5,-40],[-2,-42]],'#708e8b');}else if(type==='train'){for(let i=0;i<3;i++){const xx=i*24-42,yy=i*9;c.fillStyle='#899c8f';c.fillRect(xx,yy-22,23,18);poly(c,[[xx,yy-22],[xx+10,yy-28],[xx+33,yy-20],[xx+23,yy-13]],'#b5bd9d');for(let j=0;j<2;j++){c.fillStyle='#354e52';c.beginPath();c.arc(xx+5+j*14,yy-1,4,0,7);c.fill();}}c.fillStyle='#456368';c.fillRect(13,-13,7,11);c.fillStyle='#c9d0ac';c.fillRect(14,-12,4,5);}else if(type==='settler'){const step=walking?Math.sin(time*7)*3:0;c.strokeStyle='#534c35';c.lineWidth=4;c.beginPath();c.moveTo(-3,-12);c.lineTo(-5-step,0);c.moveTo(3,-12);c.lineTo(5+step,0);c.stroke();poly(c,[[-8,-31],[5,-33],[9,-13],[-7,-12]],'#9da884');c.fillStyle='#5a6b51';c.fillRect(-10,-30,5,15);c.fillStyle='#d8b98b';c.beginPath();c.arc(0,-39,6,0,7);c.fill();poly(c,[[-8,-41],[-5,-48],[5,-48],[8,-40]],'#9b926a');c.strokeStyle='#c8b18a';c.lineWidth=3;c.beginPath();c.moveTo(6,-27);c.lineTo(13,-19);c.stroke();c.strokeStyle='#8c7951';c.lineWidth=2;c.beginPath();c.moveTo(13,-34);c.lineTo(13,-4);c.stroke();poly(c,[[10,-8],[17,-8],[17,-2],[13,1],[10,-2]],'#9aa89b');}else{poly(c,[[-43,-3],[-24,12],[32,6],[48,-10],[20,-3]],'#786648');poly(c,[[-24,12],[32,6],[36,0],[-28,5]],'#b29a68');poly(c,[[-39,-6],[-5,-17],[41,-10],[19,1]],'#c1b384');if(type==='galley'){c.strokeStyle='#5e5c43';c.lineWidth=3;c.beginPath();c.moveTo(0,-8);c.lineTo(0,-65);c.stroke();poly(c,[[1,-62],[1,-15],[31,-22]],'#d7d4ad');poly(c,[[-2,-56],[-2,-16],[-21,-27]],'#b3c1a0');}for(let i=0;i<4;i++){c.strokeStyle='#d5c399';c.lineWidth=2;c.beginPath();c.moveTo(-24+i*12,5);c.lineTo(-34+i*12,20);c.stroke();}}c.restore();}
export function earlyThumbnail(canvas,type,unit=false){canvas.width=320;canvas.height=220;const c=canvas.getContext('2d');c.setTransform(2,0,0,2,0,0);if(unit)earlyUnit(c,type,80,105,type==='settler'?1.9:1.3);else earlyBuilding(c,type,80,91,1);}
